'use strict';

// Utilities to transform operators in expressions for SQL rendering.

const { csnAsTree, predicateOperators } = require('../../parsers/XprTree');

const operatorsPerDialect = {
  __proto__: null,
  plain: {
    __proto__: null,
    '==': function equals(xpr) {
      const lhs = xpr[0];
      const rhs = xpr[2];
      xpr.length = 0;
      if (lhs?.val === null) // shorthand
        xpr.push(rhs, 'is', 'null');
      else if (rhs?.val === null)
        xpr.push(lhs, 'is', 'null');
      else
        xpr.push(lhs, 'is', 'not', 'distinct', 'from', rhs);
    },
    '!=': function unequal(xpr) {
      const lhs = xpr[0];
      const rhs = xpr[2];
      xpr.length = 0;
      if (lhs?.val === null) // shorthand
        xpr.push(rhs, 'is', 'not', 'null');
      else if (rhs?.val === null)
        xpr.push(lhs, 'is', 'not', 'null');
      else
        xpr.push(lhs, 'is', 'distinct', 'from', rhs);
    },
  },
  hana: {
    __proto__: null,
    '==': function equals(xpr) {
      const lhs = xpr[0];
      const rhs = xpr[2];
      xpr.length = 0;
      if (lhs?.val === null) { // shorthand
        xpr.push(rhs, 'is', 'null');
      }
      else if (rhs?.val === null) {
        xpr.push(lhs, 'is', 'null');
      }
      else {
        // (a IS NOT NULL AND b IS NOT NULL AND a = b) OR (a IS NULL AND b IS NULL)
        xpr.push({
          xpr: [
            {
              xpr: [ [ lhs, 'is', 'not', 'null' ], 'and', [ rhs, 'is', 'not', 'null' ], 'and', [ lhs, '=', rhs ] ],
            },
            'or',
            {
              xpr: [ [ lhs, 'is', 'null' ], 'and', [ rhs, 'is', 'null' ] ],
            },
          ],
        });
      }
    },
    '!=': function unequal(xpr) {
      const lhs = xpr[0];
      const rhs = xpr[2];
      xpr.length = 0;

      if (lhs?.val === null) { // shorthand
        xpr.push(rhs, 'is', 'not', 'null');
      }
      else if (rhs?.val === null) {
        xpr.push(lhs, 'is', 'not', 'null');
      }
      else {
        // `(a IS NULL OR b IS NULL OR a <> b) AND (a IS NOT NULL OR b IS NOT NULL)`
        xpr.push({
          xpr: [
            {
              xpr: [ [ lhs, 'is', 'null' ], 'or', [ rhs, 'is', 'null' ], 'or', [ lhs, '<>', rhs ] ],
            },
            'and',
            {
              xpr: [ [ lhs, 'is', 'not', 'null' ], 'or', [ rhs, 'is', 'not', 'null' ] ],
            },
          ],
        });
      }
    },
  },
  sqlite: {
    __proto__: null,
    '==': function equals(xpr) {
      const rhs = xpr[2];
      xpr.length = 1;
      xpr.push('is', rhs);
    },
    '!=': function unequal(xpr) {
      const rhs = xpr[2];
      xpr.length = 1;
      xpr.push('is', 'not', rhs);
    },
  },
};

operatorsPerDialect.postgres = operatorsPerDialect.plain;
operatorsPerDialect.h2 = operatorsPerDialect.plain;

/**
 * Transform non-SQL operators to ones known by SQL.  This includes `==` and `!=`.
 * Expects structurized CSN! See xprAsTree.js
 *
 * @param {object[]|object} xpr
 * @param {SqlOptions} options
 * @param {object} messageFunctions
 * @param {object} env
 * @returns {object[]}
 */
function transformExprOperators( xpr, options, messageFunctions, env ) {
  // TODO: Reduce number of function arguments
  const sqlDialect = options.sqlDialect || 'plain';
  const operators = Object.assign(Object.create(null), operatorsPerDialect[sqlDialect] || operatorsPerDialect.plain);

  if (options.booleanEquality === false) {
    // don't translate `!=` if the option is set to false (for backward compatibility with v5)
    delete operators['!='];
  }

  transformBinary(xpr);
  return xpr;

  function transformBinary( x ) {
    if (!x || typeof x !== 'object')
      return;

    if (Array.isArray(x)) {
      const op = x[1];
      if (x.length === 3 && op in operators) {
        transformBinary(x[0]); // left-hand-side
        transformBinary(x[2]); // right-hand-side
        operators[op](x);
      }
      else {
        x.forEach(transformBinary);
      }

      if (x.length > 3 && op in operators) {
        const keyword = typeof x[2] === 'string' && x[2].toLowerCase();
        // e.g. `ref != SOME (SELECT num from Base)`
        // Since semantics are unclear, reject it.
        if (keyword === 'all' || keyword === 'some' || keyword === 'any') {
          messageFunctions.error('expr-unsupported-equality', env.path, { op, keyword },
                                 'Operator $(OP) can\'t be used in combination with $(KEYWORD)');
        }
      }
    }
    else if (x.xpr) {
      transformBinary(x.xpr);
    }
  }
}

/**
 * Whether the outermost operator of a column expression is a predicate (condition).
 * Clones first because csnAsTree() restructures its input in place, and the column
 * is structurized again for real when it is rendered.
 *
 * @param {object} col CSN column
 * @returns {boolean}
 */
function isTopLevelPredicate( col ) {
  if (!Array.isArray(col.xpr))
    return false;
  return isPredicateTree(csnAsTree(structuredClone(col.xpr)));
}

function isPredicateTree( tree ) {
  const [ top ] = tree;
  if (top && !Array.isArray(top) && top.xpr) // fully parenthesized: `( … )`
    return isPredicateTree(csnAsTree(top.xpr));
  if (!Array.isArray(top))
    return false;
  const op = typeof top[0] === 'string' ? top[0] : top[1];
  return predicateOperators.has(op);
}

// HANA renders these as a value form (`CASE … END`); in predicate position they must be
// compared to `TRUE` to become a predicate again (see `addTrueComparisonToBooleanFunctions`).
// Names must match the mapped forms in `standardDatabaseFunctions` exactly (case-sensitive):
// a differently-cased name (e.g. `CONTAINS`) opts out of the mapping and stays native.
const predicateValueFunctions = new Set( [
  'contains', 'startswith', 'endswith', 'matchespattern', 'matchesPattern',
] );

/**
 * Rewrite boolean-valued OData function nodes in genuine predicate position within a
 * condition (WHERE/HAVING/ON) to `<func> = TRUE`, so the HANA value form becomes a
 * predicate. Affected are the condition itself and operands of `and`/`or`/`not` and
 * `CASE WHEN`; not operands of a comparison (`contains(x, y) = false`), value operator,
 * or function argument, where the value form must stay so the surrounding expression is
 * valid. Mutates `tree` in place.
 *
 * @param {object[]} tree Structurized condition tree (see `csnAsTree()`)
 */
function addTrueComparisonToBooleanFunctions( tree ) {
  return visit(tree, true);

  // Returns the (possibly rewritten) node so callers can write it back into their slot.
  function visit( node, inPredicate ) {
    if (!node || typeof node !== 'object')
      return node;

    if (Array.isArray(node)) {
      if (node.length === 1) { // single-element wrapper that csnAsTree() puts around the expression
        node[0] = visit(node[0], inPredicate);
      }
      else if (node[0] === 'case') {
        visitCase(node);
      }
      else if (typeof node[0] === 'string') { // prefix: `not`/`exists` keep a predicate
        const keepsPredicate = node[0] === 'not' || node[0] === 'exists';
        for (let i = 1; i < node.length; ++i)
          node[i] = visit(node[i], inPredicate && keepsPredicate);
      }
      else { // binary `[ lhs, op, rhs ]`: only `and`/`or` operands stay predicates
        const isLogical = node[1] === 'and' || node[1] === 'or';
        node[0] = visit(node[0], inPredicate && isLogical);
        node[2] = visit(node[2], inPredicate && isLogical);
      }
      return node;
    }

    if (node.func && predicateValueFunctions.has(node.func)) {
      // 3-arg `contains` is native HANA CONTAINS (a predicate), not the value form.
      const isValueForm = !(node.func === 'contains' && node.args?.length > 2);
      if (inPredicate && isValueForm)
        return [ node, '=', { val: true } ];
    }
    else if (node.xpr) {
      if (node.xpr[0] === 'case')
        visitCase(node.xpr);
      else
        node.xpr = visit(csnAsTree(node.xpr), inPredicate);
    }
    return node;
  }

  // In a searched CASE (`case when <cond> …`) the element after `when` is a condition; in a
  // simple CASE (`case <op> when <val> …`) it is a value compared to the operand, so nothing
  // is a predicate. A non-string node before the first `when` marks the simple form.
  function visitCase( xpr ) {
    const isSimple = xpr[1] != null && typeof xpr[1] === 'object';
    for (let i = 0; i < xpr.length; ++i) {
      const kw = typeof xpr[i] === 'string' && xpr[i].toLowerCase();
      if (kw === 'when' || kw === 'then' || kw === 'else') {
        if (xpr[i + 1] && typeof xpr[i + 1] === 'object')
          xpr[i + 1] = visit(csnAsTree([ xpr[i + 1] ]), !isSimple && kw === 'when');
        i += 1;
      }
      else if (i === 1 && isSimple) { // the simple-CASE operand is a value
        xpr[i] = visit(csnAsTree([ xpr[i] ]), false);
      }
    }
  }
}

module.exports = {
  transformExprOperators,
  isTopLevelPredicate,
  addTrueComparisonToBooleanFunctions,
};
